define('taoTestRunnerPlugins/runner/plugins/accessibility/defaultHeading',['jquery', 'i18n', 'taoTests/runner/plugin'], function ($, __, pluginFactory) {
  'use strict';

  var defaultHeadingText = __('Assessment Item');
  var headingCss = {
    border: 0,
    clip: 'rect(0 0 0 0)',
    height: '1px',
    margin: '-1px',
    overflow: 'hidden',
    padding: '0',
    position: 'absolute',
    width: '1px'
  };
  return pluginFactory({
    name: 'defaultHeading',
    init: function init() {
      var testRunner = this.getTestRunner();
      var config = this.getConfig();
      var headingText = config.heading || defaultHeadingText;
      var headingTag;
      testRunner.on('renderitem', function () {
        var headingTagsCount = $('.content-wrap h1').length;
        if (headingTagsCount) {
          if (headingTag) {
            headingTag.remove();
            headingTag = undefined;
          }
          return;
        } else if (headingTag) {
          return;
        }
        headingTag = $('<h1>' + headingText + '</h1>').css(headingCss).attr('id', 'defaultHeading');
        $('body').prepend(headingTag);
      });
    },
    destroy: function destroy() {
      $('#defaultHeading').remove();
    }
  });
});
